export function pharmaciesForCity(city: string): PharmacyPoint[] { return allPharmacies.filter((p) => p.city === city); }
export function cityCenter(city: string): [number, number] { return cityCenters[city] ?? [43.238, 76.945]; }

/** Расстояние между двумя точками в км (haversine). */
export function distanceKm(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371, p = Math.PI / 180;
  const a = 0.5 - Math.cos((lat2 - lat1) * p) / 2 + Math.cos(lat1 * p) * Math.cos(lat2 * p) * (1 - Math.cos((lon2 - lon1) * p)) / 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

/** Ближайший город сети к координатам — чтобы подгрузить его аптеки. null, если дальше ~150 км от любого. */
export function nearestCity(lat: number, lon: number): string | null {
  let best: string | null = null, bestKm = Infinity;
  for (const [c, cc] of Object.entries(cityCenters)) {
    const km = distanceKm(lat, lon, cc[0], cc[1]);
    if (km < bestKm) { bestKm = km; best = c; }
  }
  return bestKm <= 150 ? best : null;
}
export const almatyPharmacies = pharmaciesForCity("Алматы");
export const yandexRoute = (p: PharmacyPoint) =>
  `https://yandex.kz/maps/?mode=routes&rtext=~${p.lat}%2C${p.lon}&rtt=auto`;
